//! Port of `Visibility.generate` (Measure/LeakRun.cs): rebuilds visible.tsv from the drawing
//! code (`fastsim-rs measure visibility [--write] [--root R]`, the same file as C#).
//!
//! C# finds a type's fields and no-argument methods by reflection; here the fields come from
//! `fields.rs` (`class_fields`) and the methods from `methods.rs` (generated by
//! `gen/rs_methods.py`, gen/README.md). The regexes of C# are matched by hand (the crate has no regex):
//! each matcher below names the pattern it stands for.
use std::collections::HashSet;
use std::path::{Path, PathBuf};

use super::fields;
use super::leak_run::Visibility;
use super::methods::STATE_TYPES;

/// .NET `\w`: letters, digits, marks and connector punctuation (`_`).
fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

/// `File.ReadAllText`: the text without a byte order mark.
fn read_text(p: &Path) -> Result<String, String> {
    std::fs::read_to_string(p)
        .map(|s| s.trim_start_matches('\u{feff}').to_string())
        .map_err(|e| format!("Could not find file '{}': {}", p.display(), e))
}

/// `Directory.GetFiles(dir, "*.gd")`.
fn gd_files(dir: &Path) -> Result<Vec<PathBuf>, String> {
    let rd = std::fs::read_dir(dir).map_err(|e| format!("Could not find a part of the path '{}': {}", dir.display(), e))?;
    let mut res: Vec<PathBuf> = rd
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.is_file() && p.extension().map(|x| x == "gd").unwrap_or(false))
        .collect();
    res.sort();
    Ok(res)
}

/// `var\s+(\w+)\s*(?::=|:\s*\w+\s*=)\s*[\w.]*\b(?:WORDS)\s*\r?$` (Multiline), every
/// non-overlapping match, group 1.
fn local_names(s: &str, words: &[&str]) -> Vec<String> {
    let c: Vec<char> = s.chars().collect();
    let n = c.len();
    let ws = |i: usize| i < n && c[i].is_whitespace();
    let mut res = Vec::new();
    let mut p = 0;
    while p + 3 <= n {
        if !(c[p] == 'v' && c[p + 1] == 'a' && c[p + 2] == 'r') {
            p += 1;
            continue;
        }
        let m = (|| -> Option<(String, usize)> {
            let mut i = p + 3;
            // \s+
            if !ws(i) {
                return None;
            }
            while ws(i) {
                i += 1;
            }
            // (\w+)
            let n0 = i;
            while i < n && is_word(c[i]) {
                i += 1;
            }
            if i == n0 {
                return None;
            }
            let name: String = c[n0..i].iter().collect();
            // \s*
            while ws(i) {
                i += 1;
            }
            // (?::=|:\s*\w+\s*=)
            if i >= n || c[i] != ':' {
                return None;
            }
            i += 1;
            if i < n && c[i] == '=' {
                i += 1;
            } else {
                while ws(i) {
                    i += 1;
                }
                let t0 = i;
                while i < n && is_word(c[i]) {
                    i += 1;
                }
                if i == t0 {
                    return None;
                }
                while ws(i) {
                    i += 1;
                }
                if i >= n || c[i] != '=' {
                    return None;
                }
                i += 1;
            }
            // \s*
            while ws(i) {
                i += 1;
            }
            // [\w.]*\b(?:WORDS): the run of [\w.] must end in a word whose start is a boundary.
            let r0 = i;
            while i < n && (is_word(c[i]) || c[i] == '.') {
                i += 1;
            }
            let run: String = c[r0..i].iter().collect();
            let ok = words.iter().any(|w| {
                run.ends_with(w) && {
                    let at = run.chars().count() - w.chars().count();
                    let before = if at > 0 { Some(c[r0 + at - 1]) } else if r0 > 0 { Some(c[r0 - 1]) } else { None };
                    before.map(|b| !is_word(b)).unwrap_or(true)
                }
            });
            if !ok {
                return None;
            }
            // \s*\r?$ (Multiline: at the end or before a '\n'; \s* may run over line ends)
            let mut j = i;
            let mut end = None;
            loop {
                if j == n || c[j] == '\n' {
                    end = Some(j);
                }
                if ws(j) {
                    j += 1;
                } else {
                    break;
                }
            }
            end.map(|e| (name, e))
        })();
        match m {
            Some((name, e)) => {
                res.push(name);
                p = e.max(p + 1);
            }
            None => p += 1,
        }
    }
    res
}

/// `\b(?:ALTS)\.([a-z_][a-z0-9_]*)`, every non-overlapping match, group 1.
fn member_names(s: &str, alts: &[String]) -> Vec<String> {
    let c: Vec<char> = s.chars().collect();
    let n = c.len();
    let mut res = Vec::new();
    let mut p = 0;
    while p < n {
        if p > 0 && is_word(c[p - 1]) || !is_word(c[p]) {
            p += 1;
            continue;
        }
        let mut hit = None;
        for a in alts {
            let a: Vec<char> = a.chars().collect();
            let e = p + a.len();
            if e < n && c[p..e] == a[..] && c[e] == '.' {
                let f0 = e + 1;
                if f0 < n && (c[f0].is_ascii_lowercase() || c[f0] == '_') {
                    let mut f = f0 + 1;
                    while f < n && (c[f].is_ascii_lowercase() || c[f].is_ascii_digit() || c[f] == '_') {
                        f += 1;
                    }
                    hit = Some((c[f0..f].iter().collect::<String>(), f));
                    break;
                }
            }
        }
        match hit {
            Some((name, f)) => {
                res.push(name);
                p = f;
            }
            None => p += 1,
        }
    }
    res
}

/// `Regex.Replace(name, "(?<!^)([A-Z])", "_$1").ToLowerInvariant()`: BossSaw -> boss_saw.
fn snake(name: &str) -> String {
    let mut s = String::new();
    for (i, ch) in name.chars().enumerate() {
        if i > 0 && ch.is_ascii_uppercase() {
            s.push('_');
        }
        s.push(ch);
    }
    s.to_lowercase()
}

/// `Visibility.no_arg_method(t, name) != null`.
fn has_no_arg_method(class: &str, name: &str) -> bool {
    STATE_TYPES.iter().any(|(c, ms)| *c == class && ms.contains(&name))
}

/// No-argument sim methods the Rust port has inlined (no method to call), by the fields
/// their result is made of: a view that calls one shows those fields. Without this the
/// lane a Hunter Spike's dashed line marks (`h.shot_lanes()`) was listed as hidden.
const INLINED: &[(&str, &str, &[&str])] = &[("Dart", "shot_lanes", &["lane_y", "pair", "lane2_y"])];

pub const HEADER: &str = "# Fields the screen shows (deny by default: every other field is hidden). Built by `fastsim measure visibility --write` from game/run.\n";

/// Rebuilds the visible list from the drawing code and the sim's sources.
pub fn generate(root: &Path) -> Result<Vec<String>, String> {
    let mut rows: Vec<(String, String)> = Vec::new();
    let game = root.join("game").join("run");
    // A name the drawing code reads is a field (visible as it is) or a method; a method the
    // view calls without arguments is visible by its result (its inputs may stay hidden:
    // a tide's salt is not on screen, the tide's depth now is). Methods with arguments
    // are geometry of fields already listed.
    let add = |rows: &mut Vec<(String, String)>, class: &str, names: &[String], from: &str| {
        let fs: HashSet<&str> = fields::class_fields(class).iter().map(|f| f.name).collect();
        let mut seen: HashSet<&str> = HashSet::new();
        for nm in names {
            if !seen.insert(nm.as_str()) {
                continue;
            }
            if fs.contains(nm.as_str()) {
                rows.push((format!("{}.{}", class, nm), from.to_string()));
            } else if has_no_arg_method(class, nm) {
                rows.push((format!("{}.{}()", class, nm), from.to_string()));
            } else if let Some((_, _, of)) = INLINED.iter().find(|(c, m, _)| *c == class && *m == nm.as_str()) {
                for f in of.iter() {
                    rows.push((format!("{}.{}", class, f), from.to_string()));
                }
            }
        }
    };
    let mut views = gd_files(&game)?;
    views.extend(gd_files(&game.join("painters"))?);
    let mut state_names: Vec<String> = Vec::new();
    let mut room_names: Vec<String> = Vec::new();
    for p in &views {
        let s = read_text(p)?;
        // Local names for the state and the room ("var s := _run.sim.state").
        let mut st: Vec<String> = vec!["state".into(), "prev_state".into()];
        let mut rm: Vec<String> = vec!["room".into()];
        st.extend(local_names(&s, &["state", "prev_state"]));
        rm.extend(local_names(&s, &["room"]));
        state_names.extend(member_names(&s, &st));
        room_names.extend(member_names(&s, &rm));
    }
    add(&mut rows, "SimState", &state_names, "game/run/*.gd state.<field>");
    add(&mut rows, "RoomRuntime", &room_names, "game/run/*.gd room.<field>");
    for (class, _) in STATE_TYPES.iter().skip(2) {
        let kind = snake(class);
        let painter = game.join("painters").join(format!("{}_painter.gd", kind));
        if !painter.is_file() {
            continue;
        }
        let s = read_text(&painter)?;
        let mut names = member_names(&s, &["h".to_string()]);
        // Every hazard's position and life are drawn by the layer itself.
        names.extend(["alive", "x", "y"].iter().map(|x| x.to_string()));
        add(&mut rows, class, &names, &format!("game/run/painters/{}_painter.gd", kind));
    }
    // rows.Distinct().OrderBy(r => r.key) (ordinal: the C# build has InvariantGlobalization)
    let mut seen: HashSet<(String, String)> = HashSet::new();
    rows.retain(|r| seen.insert(r.clone()));
    rows.sort_by(|a, b| a.0.cmp(&b.0));
    Ok(rows.into_iter().map(|(k, f)| format!("{}\t{}", k, f)).collect())
}

/// `Path.GetFullPath`: an absolute path with `.` and `..` folded away.
pub fn full_path(p: &Path) -> PathBuf {
    let abs = std::path::absolute(p).unwrap_or_else(|_| p.to_path_buf());
    let mut out_ = PathBuf::new();
    for c in abs.components() {
        match c {
            std::path::Component::ParentDir => {
                out_.pop();
            }
            std::path::Component::CurDir => {}
            x => out_.push(x.as_os_str()),
        }
    }
    out_
}

/// The repository root: visible.tsv's folder, three up (tools/fastsim-rs/data).
pub fn default_root() -> PathBuf {
    full_path(&Path::new(&Visibility::file()).parent().unwrap_or(Path::new(".")).join("..").join("..").join(".."))
}

/// `measure visibility [--write] [--root R]`.
pub fn run(root: Option<&String>, write: bool) -> Result<i32, String> {
    let root = match root {
        Some(r) => full_path(Path::new(r)),
        None => default_root(),
    };
    let rows = generate(&root)?;
    let text = HEADER.to_string() + &rows.join("\n") + "\n";
    let file = full_path(Path::new(&Visibility::file()));
    if write {
        std::fs::write(&file, &text).map_err(|e| format!("{}: {}", file.display(), e))?;
    } else {
        print!("{}", text);
    }
    eprintln!(
        "{} visible fields{}",
        rows.len(),
        if write { format!(" written to {}", file.display()) } else { String::new() }
    );
    Ok(0)
}
